-- ============================================================
-- Letterboxd Clone - COMPLETE PostgreSQL schema + lived-in data
-- Generated from the supplied lived-in seed and migrations 001-005.
--
-- This is a SELF-CONTAINED development database script:
--   1) creates the complete schema (base tables + migrations 001-005)
--   2) loads the large lived-in seed
--   3) adds realistic data for diary/comments/favorites/movie likes/tags
--
-- WARNING: running this file resets the Letterboxd application tables.
-- Seeded test-user password: Test1234!
-- ============================================================

BEGIN;

-- Drop application tables so this script can be re-run on a development DB.
DROP TABLE IF EXISTS movie_likes CASCADE;
DROP TABLE IF EXISTS user_favorite_movies CASCADE;
DROP TABLE IF EXISTS diary_entries CASCADE;
DROP TABLE IF EXISTS review_comments CASCADE;
DROP TABLE IF EXISTS review_likes CASCADE;
DROP TABLE IF EXISTS list_movies CASCADE;
DROP TABLE IF EXISTS follows CASCADE;
DROP TABLE IF EXISTS reviews CASCADE;
DROP TABLE IF EXISTS ratings CASCADE;
DROP TABLE IF EXISTS watched_movies CASCADE;
DROP TABLE IF EXISTS watchlist CASCADE;
DROP TABLE IF EXISTS movie_genres CASCADE;
DROP TABLE IF EXISTS movie_lists CASCADE;
DROP TABLE IF EXISTS genres CASCADE;
DROP TABLE IF EXISTS movies CASCADE;
DROP TABLE IF EXISTS users CASCADE;
DROP FUNCTION IF EXISTS set_updated_at() CASCADE;

-- ------------------------------------------------------------
-- Shared updated_at trigger function
-- ------------------------------------------------------------
CREATE FUNCTION set_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$;

-- ------------------------------------------------------------
-- 1. users
-- ------------------------------------------------------------
CREATE TABLE users (
    id              BIGSERIAL PRIMARY KEY,
    username        VARCHAR(50) NOT NULL UNIQUE,
    email           VARCHAR(255) NOT NULL UNIQUE,
    password_hash   TEXT NOT NULL,
    avatar_url      TEXT,
    bio             TEXT,
    created_at      TIMESTAMP NOT NULL DEFAULT now(),
    updated_at      TIMESTAMP NOT NULL DEFAULT now(),
    CONSTRAINT username_not_empty CHECK (btrim(username) <> ''),
    CONSTRAINT email_not_empty CHECK (btrim(email) <> ''),
    CONSTRAINT bio_length CHECK (bio IS NULL OR char_length(bio) <= 1000)
);

CREATE INDEX idx_users_username_lower ON users (lower(username));
CREATE INDEX idx_users_email_lower ON users (lower(email));

CREATE TRIGGER trg_users_updated_at
BEFORE UPDATE ON users
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ------------------------------------------------------------
-- 2. movies
-- ------------------------------------------------------------
CREATE TABLE movies (
    id              BIGSERIAL PRIMARY KEY,
    title           TEXT NOT NULL,
    release_year    INTEGER,
    director        TEXT,
    overview        TEXT,
    runtime         INTEGER,
    actors          TEXT[] NOT NULL DEFAULT '{}',
    keywords        TEXT[] NOT NULL DEFAULT '{}',
    poster_url      TEXT,
    backdrop_url    TEXT,
    created_at      TIMESTAMP NOT NULL DEFAULT now(),
    updated_at      TIMESTAMP NOT NULL DEFAULT now(),
    CONSTRAINT movie_title_not_empty CHECK (btrim(title) <> ''),
    CONSTRAINT valid_release_year CHECK (release_year IS NULL OR release_year BETWEEN 1800 AND 2200),
    CONSTRAINT valid_runtime CHECK (runtime IS NULL OR runtime > 0)
);

CREATE INDEX idx_movies_title_lower ON movies (lower(title));
CREATE INDEX idx_movies_release_year ON movies (release_year);
CREATE INDEX idx_movies_director_lower ON movies (lower(director));
CREATE INDEX idx_movies_actors ON movies USING gin (actors);
CREATE INDEX idx_movies_keywords ON movies USING gin (keywords);

CREATE TRIGGER trg_movies_updated_at
BEFORE UPDATE ON movies
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ------------------------------------------------------------
-- 3. genres
-- ------------------------------------------------------------
CREATE TABLE genres (
    id      BIGSERIAL PRIMARY KEY,
    name    VARCHAR(100) NOT NULL UNIQUE,
    CONSTRAINT genre_name_not_empty CHECK (btrim(name) <> '')
);

-- ------------------------------------------------------------
-- 4. movie_genres
-- ------------------------------------------------------------
CREATE TABLE movie_genres (
    movie_id    BIGINT NOT NULL REFERENCES movies(id) ON DELETE CASCADE,
    genre_id    BIGINT NOT NULL REFERENCES genres(id) ON DELETE CASCADE,
    PRIMARY KEY (movie_id, genre_id)
);

CREATE INDEX idx_movie_genres_genre_id ON movie_genres(genre_id);

-- ------------------------------------------------------------
-- 5. ratings
-- One current rating per user/movie, in Letterboxd half-star steps.
-- ------------------------------------------------------------
CREATE TABLE ratings (
    id          BIGSERIAL PRIMARY KEY,
    user_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    movie_id    BIGINT NOT NULL REFERENCES movies(id) ON DELETE CASCADE,
    rating      NUMERIC(2,1) NOT NULL,
    created_at  TIMESTAMP NOT NULL DEFAULT now(),
    updated_at  TIMESTAMP NOT NULL DEFAULT now(),
    UNIQUE (user_id, movie_id),
    CONSTRAINT valid_rating CHECK (
        rating BETWEEN 0.5 AND 5.0
        AND (rating * 2) = trunc(rating * 2)
    )
);

CREATE INDEX idx_ratings_user_id ON ratings(user_id);
CREATE INDEX idx_ratings_movie_id ON ratings(movie_id);
CREATE INDEX idx_ratings_movie_rating ON ratings(movie_id, rating);

CREATE TRIGGER trg_ratings_updated_at
BEFORE UPDATE ON ratings
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ------------------------------------------------------------
-- 6. watched_movies
-- Simple watched status. Diary history is stored separately below.
-- ------------------------------------------------------------
CREATE TABLE watched_movies (
    id          BIGSERIAL PRIMARY KEY,
    user_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    movie_id    BIGINT NOT NULL REFERENCES movies(id) ON DELETE CASCADE,
    watched_at  TIMESTAMP NOT NULL DEFAULT now(),
    UNIQUE (user_id, movie_id)
);

CREATE INDEX idx_watched_movies_user_id ON watched_movies(user_id);
CREATE INDEX idx_watched_movies_movie_id ON watched_movies(movie_id);
CREATE INDEX idx_watched_movies_watched_at ON watched_movies(watched_at);

-- ------------------------------------------------------------
-- 7. watchlist
-- ------------------------------------------------------------
CREATE TABLE watchlist (
    id          BIGSERIAL PRIMARY KEY,
    user_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    movie_id    BIGINT NOT NULL REFERENCES movies(id) ON DELETE CASCADE,
    created_at  TIMESTAMP NOT NULL DEFAULT now(),
    UNIQUE (user_id, movie_id)
);

CREATE INDEX idx_watchlist_user_id ON watchlist(user_id);
CREATE INDEX idx_watchlist_movie_id ON watchlist(movie_id);
CREATE INDEX idx_watchlist_created_at ON watchlist(created_at);

-- ------------------------------------------------------------
-- 8. reviews
-- Includes migration 001: spoiler flag + tags.
-- ------------------------------------------------------------
CREATE TABLE reviews (
    id          BIGSERIAL PRIMARY KEY,
    user_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    movie_id    BIGINT NOT NULL REFERENCES movies(id) ON DELETE CASCADE,
    content     TEXT NOT NULL,
    created_at  TIMESTAMP NOT NULL DEFAULT now(),
    updated_at  TIMESTAMP NOT NULL DEFAULT now(),
    is_spoiler  BOOLEAN NOT NULL DEFAULT false,
    tags        TEXT[] NOT NULL DEFAULT '{}',
    UNIQUE (user_id, movie_id),
    CONSTRAINT review_content_not_empty CHECK (btrim(content) <> ''),
    CONSTRAINT review_content_length CHECK (char_length(content) <= 10000)
);

CREATE INDEX idx_reviews_user_id ON reviews(user_id);
CREATE INDEX idx_reviews_movie_id ON reviews(movie_id);
CREATE INDEX idx_reviews_created_at ON reviews(created_at);
CREATE INDEX idx_reviews_tags ON reviews USING gin (tags);

CREATE TRIGGER trg_reviews_updated_at
BEFORE UPDATE ON reviews
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ------------------------------------------------------------
-- 9. review_likes
-- ------------------------------------------------------------
CREATE TABLE review_likes (
    id          BIGSERIAL PRIMARY KEY,
    user_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    review_id   BIGINT NOT NULL REFERENCES reviews(id) ON DELETE CASCADE,
    created_at  TIMESTAMP NOT NULL DEFAULT now(),
    UNIQUE (user_id, review_id)
);

CREATE INDEX idx_review_likes_user_id ON review_likes(user_id);
CREATE INDEX idx_review_likes_review_id ON review_likes(review_id);

-- ------------------------------------------------------------
-- 10. follows
-- ------------------------------------------------------------
CREATE TABLE follows (
    id              BIGSERIAL PRIMARY KEY,
    follower_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    following_id    BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at      TIMESTAMP NOT NULL DEFAULT now(),
    UNIQUE (follower_id, following_id),
    CONSTRAINT cannot_follow_self CHECK (follower_id <> following_id)
);

CREATE INDEX idx_follows_follower_id ON follows(follower_id);
CREATE INDEX idx_follows_following_id ON follows(following_id);

-- ------------------------------------------------------------
-- 11. movie_lists
-- ------------------------------------------------------------
CREATE TABLE movie_lists (
    id          BIGSERIAL PRIMARY KEY,
    user_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    name        VARCHAR(150) NOT NULL,
    description TEXT,
    is_public   BOOLEAN NOT NULL DEFAULT true,
    created_at  TIMESTAMP NOT NULL DEFAULT now(),
    updated_at  TIMESTAMP NOT NULL DEFAULT now(),
    CONSTRAINT movie_list_name_not_empty CHECK (btrim(name) <> ''),
    CONSTRAINT movie_list_description_length CHECK (
        description IS NULL OR char_length(description) <= 5000
    )
);

CREATE INDEX idx_movie_lists_user_id ON movie_lists(user_id);
CREATE INDEX idx_movie_lists_public ON movie_lists(is_public);

CREATE TRIGGER trg_movie_lists_updated_at
BEFORE UPDATE ON movie_lists
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ------------------------------------------------------------
-- 12. list_movies
-- Position is numeric because the supplied seed uses values such as 1.0000.
-- ------------------------------------------------------------
CREATE TABLE list_movies (
    list_id     BIGINT NOT NULL REFERENCES movie_lists(id) ON DELETE CASCADE,
    movie_id    BIGINT NOT NULL REFERENCES movies(id) ON DELETE CASCADE,
    position    NUMERIC(12,4) NOT NULL,
    added_at    TIMESTAMP NOT NULL DEFAULT now(),
    PRIMARY KEY (list_id, movie_id),
    UNIQUE (list_id, position),
    CONSTRAINT valid_list_position CHECK (position > 0)
);

CREATE INDEX idx_list_movies_movie_id ON list_movies(movie_id);

-- ------------------------------------------------------------
-- 13. review_comments (migration 002)
-- ------------------------------------------------------------
CREATE TABLE review_comments (
    id          BIGSERIAL PRIMARY KEY,
    review_id   BIGINT NOT NULL REFERENCES reviews(id) ON DELETE CASCADE,
    user_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    content     TEXT NOT NULL,
    created_at  TIMESTAMP NOT NULL DEFAULT now(),
    updated_at  TIMESTAMP NOT NULL DEFAULT now(),
    CONSTRAINT comment_content_not_empty CHECK (btrim(content) <> '')
);

CREATE INDEX idx_review_comments_review_id ON review_comments(review_id);
CREATE INDEX idx_review_comments_user_id ON review_comments(user_id);
CREATE INDEX idx_review_comments_created_at ON review_comments(created_at);

CREATE TRIGGER trg_review_comments_updated_at
BEFORE UPDATE ON review_comments
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ------------------------------------------------------------
-- 14. diary_entries (migration 003)
-- Multiple entries per user/movie are intentionally allowed for rewatches.
-- ------------------------------------------------------------
CREATE TABLE diary_entries (
    id              BIGSERIAL PRIMARY KEY,
    user_id         BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    movie_id        BIGINT NOT NULL REFERENCES movies(id) ON DELETE CASCADE,
    watched_date    DATE NOT NULL DEFAULT CURRENT_DATE,
    is_rewatch      BOOLEAN NOT NULL DEFAULT false,
    note            TEXT,
    created_at      TIMESTAMP NOT NULL DEFAULT now(),
    CONSTRAINT note_length CHECK (note IS NULL OR char_length(note) <= 1000)
);

CREATE INDEX idx_diary_entries_user_id ON diary_entries(user_id);
CREATE INDEX idx_diary_entries_movie_id ON diary_entries(movie_id);
CREATE INDEX idx_diary_entries_watched_date ON diary_entries(watched_date);
CREATE INDEX idx_diary_entries_user_date ON diary_entries(user_id, watched_date DESC);

-- ------------------------------------------------------------
-- 15. user_favorite_movies (migration 004)
-- ------------------------------------------------------------
CREATE TABLE user_favorite_movies (
    user_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    movie_id    BIGINT NOT NULL REFERENCES movies(id) ON DELETE CASCADE,
    position    SMALLINT NOT NULL,
    PRIMARY KEY (user_id, position),
    UNIQUE (user_id, movie_id),
    CONSTRAINT valid_position CHECK (position BETWEEN 1 AND 4)
);

CREATE INDEX idx_user_favorite_movies_movie_id ON user_favorite_movies(movie_id);

-- ------------------------------------------------------------
-- 16. movie_likes (migration 005)
-- ------------------------------------------------------------
CREATE TABLE movie_likes (
    id          BIGSERIAL PRIMARY KEY,
    user_id     BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    movie_id    BIGINT NOT NULL REFERENCES movies(id) ON DELETE CASCADE,
    created_at  TIMESTAMP NOT NULL DEFAULT now(),
    UNIQUE (user_id, movie_id)
);

CREATE INDEX idx_movie_likes_user_id ON movie_likes(user_id);
CREATE INDEX idx_movie_likes_movie_id ON movie_likes(movie_id);
CREATE INDEX idx_movie_likes_created_at ON movie_likes(created_at);

COMMIT;

-- ============================================================
-- LARGE LIVED-IN BASE SEED
-- 250 users, 1000 real-metadata movies, and tens of thousands of
-- ratings/watches/watchlist items/reviews/likes/follows/lists.
-- ============================================================

-- Letterboxd Clone - lived-in development seed
-- Movies and movie metadata are preserved from the real TMDB-based seed.
-- User activity is synthetic development data designed to resemble an active app.
-- UTF-8 without BOM. Invisible Unicode control/format characters removed.
--
-- This file DELETES existing application data before inserting the new seed.
-- Test password for seeded users remains: Test1234!

BEGIN;

TRUNCATE TABLE
    review_likes,
    list_movies,
    follows,
    reviews,
    ratings,
    watched_movies,
    watchlist,
    movie_genres,
    movie_lists,
    genres,
    movies,
    users
RESTART IDENTITY CASCADE;

-- users

-- movies: REAL movie metadata

-- genres derived from real films

-- movie_genres: preserves all genres available in source metadata

-- ratings - 20000 lived-in records

-- watched_movies - every rated movie is watched, plus watched-but-unrated films

-- watchlist - contains only films the user has not watched

-- reviews - subset of rated movies

-- review_likes

-- follows - active users naturally form more visible hubs

-- movie_lists

-- list_movies

SELECT setval(pg_get_serial_sequence('users','id'), (SELECT MAX(id) FROM users), true);
SELECT setval(pg_get_serial_sequence('movies','id'), (SELECT MAX(id) FROM movies), true);
SELECT setval(pg_get_serial_sequence('genres','id'), (SELECT MAX(id) FROM genres), true);
SELECT setval(pg_get_serial_sequence('ratings','id'), (SELECT MAX(id) FROM ratings), true);
SELECT setval(pg_get_serial_sequence('watched_movies','id'), (SELECT MAX(id) FROM watched_movies), true);
SELECT setval(pg_get_serial_sequence('watchlist','id'), (SELECT MAX(id) FROM watchlist), true);
SELECT setval(pg_get_serial_sequence('reviews','id'), (SELECT MAX(id) FROM reviews), true);
SELECT setval(pg_get_serial_sequence('review_likes','id'), (SELECT MAX(id) FROM review_likes), true);
SELECT setval(pg_get_serial_sequence('follows','id'), (SELECT MAX(id) FROM follows), true);
SELECT setval(pg_get_serial_sequence('movie_lists','id'), (SELECT MAX(id) FROM movie_lists), true);

COMMIT;


-- ============================================================
-- EXTRA LIVED-IN ACTIVITY FOR FEATURES ADDED BY MIGRATIONS 001-005
-- ============================================================
BEGIN;

-- Migration 001 data: make review tags/spoiler state look organically used.
UPDATE reviews
SET
    is_spoiler = (id % 17 = 0),
    tags = CASE
        WHEN id % 33 = 0 THEN ARRAY['rewatch','favorite','cinematography']::TEXT[]
        WHEN id % 22 = 0 THEN ARRAY['rewatch','performance']::TEXT[]
        WHEN id % 15 = 0 THEN ARRAY['favorite']::TEXT[]
        WHEN id % 10 = 0 THEN ARRAY['cinematography']::TEXT[]
        WHEN id % 7  = 0 THEN ARRAY['performance']::TEXT[]
        WHEN id % 5  = 0 THEN ARRAY['first-watch']::TEXT[]
        ELSE '{}'::TEXT[]
    END;

-- Migration 002 data: thousands of comments spread across existing reviews.
SELECT
    r.id,
    CASE
        WHEN (((r.user_id + r.id * 7 - 1) % 250) + 1) = r.user_id
            THEN ((r.user_id % 250) + 1)
        ELSE (((r.user_id + r.id * 7 - 1) % 250) + 1)
    END AS commenter_id,
    CASE (r.id % 8)
        WHEN 0 THEN 'Totally agree with this take.'
        WHEN 1 THEN 'I had almost the same reaction after watching it.'
        WHEN 2 THEN 'The cinematography was the part that stayed with me most.'
        WHEN 3 THEN 'Interesting point — I read that scene a little differently.'
        WHEN 4 THEN 'Adding this to my watchlist after reading your review.'
        WHEN 5 THEN 'That ending worked much better for me on a rewatch.'
        WHEN 6 THEN 'The performances really carried this one for me.'
        ELSE 'Good review. This makes me want to revisit the film.'
    END,
    r.created_at + ((r.id % 36) + 1) * INTERVAL '1 hour',
    r.created_at + ((r.id % 36) + 1) * INTERVAL '1 hour'
FROM reviews r
WHERE r.id % 2 = 0;

-- A second conversation reply on a smaller subset of reviews.
SELECT
    r.id,
    CASE
        WHEN (((r.user_id + r.id * 13 - 1) % 250) + 1) = r.user_id
            THEN (((r.user_id + 1) % 250) + 1)
        ELSE (((r.user_id + r.id * 13 - 1) % 250) + 1)
    END AS commenter_id,
    CASE (r.id % 5)
        WHEN 0 THEN 'Same here. I noticed even more details the second time.'
        WHEN 1 THEN 'I can see that. The pacing is definitely going to divide people.'
        WHEN 2 THEN 'This is exactly why I love reading other people''s interpretations.'
        WHEN 3 THEN 'The score deserves a mention too — it adds so much to the atmosphere.'
        ELSE 'Fair take. I liked it a bit more, but I get where you are coming from.'
    END,
    r.created_at + ((r.id % 60) + 40) * INTERVAL '1 hour',
    r.created_at + ((r.id % 60) + 40) * INTERVAL '1 hour'
FROM reviews r
WHERE r.id % 5 = 0;

-- Migration 003 data: every watched movie gets an initial diary entry.
SELECT
    w.user_id,
    w.movie_id,
    w.watched_at::date,
    false,
    CASE
        WHEN w.id % 29 = 0 THEN 'Great late-night watch.'
        WHEN w.id % 37 = 0 THEN 'Watched with friends.'
        WHEN w.id % 43 = 0 THEN 'Finally got around to this one.'
        ELSE NULL
    END,
    w.watched_at
FROM watched_movies w;

-- Add genuine rewatch history for a subset, while keeping dates before Sep 2026.
SELECT
    w.user_id,
    w.movie_id,
    (w.watched_at + ((14 + (w.id % 45)) * INTERVAL '1 day'))::date,
    true,
    CASE
        WHEN w.id % 22 = 0 THEN 'Rewatch — even better this time.'
        WHEN w.id % 33 = 0 THEN 'Caught a lot of details I missed before.'
        ELSE NULL
    END,
    w.watched_at + ((14 + (w.id % 45)) * INTERVAL '1 day')
FROM watched_movies w
WHERE w.id % 11 = 0
  AND w.watched_at::date <= DATE '2026-07-05';

-- Migration 004 data: give each seeded user up to four plausible favorites.
-- In the real app these are manually curated; for seed data we derive them
-- from each user's strongest ratings so profiles look populated immediately.
WITH ranked AS (
    SELECT
        r.user_id,
        r.movie_id,
        ROW_NUMBER() OVER (
            PARTITION BY r.user_id
            ORDER BY r.rating DESC, r.updated_at DESC, r.movie_id
        ) AS position
    FROM ratings r
)
SELECT user_id, movie_id, position::SMALLINT
FROM ranked
WHERE position <= 4;

-- Migration 005 data: movie hearts are separate from ratings/review likes.
-- High ratings usually imply a like; a minority of 3.5-star ratings are liked too.
SELECT
    r.user_id,
    r.movie_id,
    r.created_at + ((r.id % 180) + 5) * INTERVAL '1 minute'
FROM ratings r
WHERE r.rating >= 4.0
   OR (r.rating = 3.5 AND r.id % 4 = 0);

-- Keep sequences correct after explicit/imported IDs.
SELECT setval(pg_get_serial_sequence('review_comments','id'), COALESCE((SELECT MAX(id) FROM review_comments), 1), true);
SELECT setval(pg_get_serial_sequence('diary_entries','id'), COALESCE((SELECT MAX(id) FROM diary_entries), 1), true);
SELECT setval(pg_get_serial_sequence('movie_likes','id'), COALESCE((SELECT MAX(id) FROM movie_likes), 1), true);

COMMIT;

