INSERT INTO movies (id, title, release_year, director, overview, runtime, actors, keywords, poster_url, backdrop_url, created_at, updated_at) VALUES
(1,'The Dark Knight',2008,'Christopher Nolan','Batman raises the stakes in his war on crime. With the help of Lt. Jim Gordon and District Attorney Harvey Dent, Batman sets out to dismantle the remaining criminal organizations that plague the streets. The partnership proves to be effective, but they soon find themselves prey to a reign of chaos unleashed by a rising criminal mastermind known to the terrified citizens of Gotham as the Joker.',152,ARRAY['Christian Bale','Heath Ledger','Aaron Eckhart','Michael Caine','Maggie Gyllenhaal','Gary Oldman','Morgan Freeman','Monique Gabriela Curnen']::TEXT[],ARRAY['crime fighter','secret identity','anti hero','scarecrow','sadism','chaos','vigilante','superhero','based on comic','tragic hero','organized crime','anti villain','criminal mastermind','district attorney','super power']::TEXT[],'https://image.tmdb.org/t/p/w500/qJ2tW6WMUDux911r6m7haRef0WH.jpg',NULL,'2026-01-01 00:01:00','2026-01-01 00:01:00'),
(2,'Fight Club',1999,'David Fincher','A ticking-time-bomb insomniac and a slippery soap salesman channel primal male aggression into a shocking new form of therapy. Their concept catches on, with underground "fight clubs" forming in every town, until an eccentric gets in the way and ignites an out-of-control spiral toward oblivion.',139,ARRAY['Edward Norton','Brad Pitt','Helena Bonham Carter','Meat Loaf','Jared Leto','Zach Grenier','Holt McCallany','Eion Bailey']::TEXT[],ARRAY['based on novel or book','support group','dual identity','nihilism','fight','rage and hate','insomnia','dystopia','alter ego','breaking the fourth wall','split personality','quitting a job','dissociative identity disorder','self destructiveness']::TEXT[],'https://image.tmdb.org/t/p/w500/jSziioSwPVrOy9Yow3XhWIBDjq1.jpg',NULL,'2026-01-01 00:02:00','2026-01-01 00:02:00'),
(3,'Pulp Fiction',1994,'Quentin Tarantino','A burger-loving hit man, his philosophical partner, a drug-addled gangster''s moll and a washed-up boxer converge in this sprawling, comedic crime caper. Their adventures unfurl in three stories that ingeniously trip back and forth in time.',154,ARRAY['John Travolta','Samuel L. Jackson','Uma Thurman','Bruce Willis','Ving Rhames','Harvey Keitel','Eric Stoltz','Tim Roth']::TEXT[],ARRAY['drug crime','drug dealer','gangster','stolen money','crime boss','dark comedy','redemption','los angeles','california','theft','couple','nonlinear timeline','multiple storylines','aggressive','neo-noir']::TEXT[],'https://image.tmdb.org/t/p/w500/vQWk5YBFWF4bZaofAbv0tShwBvQ.jpg',NULL,'2026-01-01 00:03:00','2026-01-01 00:03:00'),
(4,'Forrest Gump',1994,'Robert Zemeckis','A man with a low IQ has accomplished great things in his life and been present during significant historic events—in each case, far exceeding what anyone imagined he could do. But despite all he has achieved, his one true love eludes him.',142,ARRAY['Tom Hanks','Robin Wright','Gary Sinise','Sally Field','Mykelti Williamson','Michael Conner Humphreys','Hanna Hall','Haley Joel Osment']::TEXT[],ARRAY['vietnam veteran','post-traumatic stress disorder (ptsd)','hippie','washington dc','usa','new year''s eve','single parent','mentally disabled','based on novel or book','waitress','usa president','optimism','parent child relationship','1970s','autism']::TEXT[],'https://image.tmdb.org/t/p/w500/Cw4hIUIAmSYfK9QfaUW5igp9La.jpg',NULL,'2026-01-01 00:04:00','2026-01-01 00:04:00'),
(5,'Harry Potter and the Philosopher''s Stone',2001,'Chris Columbus','Harry Potter has lived under the stairs at his aunt and uncle''s house his whole life. But on his 11th birthday, he learns he''s a powerful wizard—with a place waiting for him at the Hogwarts School of Witchcraft and Wizardry. As he learns to harness his newfound powers with the help of the school''s kindly headmaster, Harry uncovers the truth about his parents'' deaths—and about the villain who''s to blame.',152,ARRAY['Daniel Radcliffe','Rupert Grint','Emma Watson','Richard Harris','Tom Felton','Alan Rickman','Robbie Coltrane','Maggie Smith']::TEXT[],ARRAY['london','england','witch','based on novel or book','magic','school friend','male friendship','child hero','school of witchcraft','chosen one','friendship','boarding school','bullying','school','ghost']::TEXT[],'https://image.tmdb.org/t/p/w500/wuMc08IPKEatf9rnMNXvIDxqP4W.jpg',NULL,'2026-01-01 00:05:00','2026-01-01 00:05:00'),
(6,'Iron Man',2008,'Jon Favreau','After being held captive in an Afghan cave, billionaire engineer Tony Stark creates a unique weaponized suit of armor to fight evil.',126,ARRAY['Robert Downey Jr.','Terrence Howard','Jeff Bridges','Gwyneth Paltrow','Leslie Bibb','Shaun Toub','Faran Tahir','Clark Gregg']::TEXT[],ARRAY['middle east','kidnapping','arms dealer','superhero','based on comic','aftercreditsstinger','marvel cinematic universe (mcu)','aggressive','counterterrorism','antagonistic','bold']::TEXT[],'https://image.tmdb.org/t/p/w500/78lPtwv72eTNqFW9COBYI0dWDJa.jpg',NULL,'2026-01-01 00:06:00','2026-01-01 00:06:00'),
(7,'The Matrix',1999,'Lana Wachowski, Lilly Wachowski','Set in the 22nd century, The Matrix tells the story of a computer hacker who joins a group of underground insurgents fighting the vast and powerful computers who now rule the earth.',136,ARRAY['Keanu Reeves','Laurence Fishburne','Carrie-Anne Moss','Hugo Weaving','Gloria Foster','Joe Pantoliano','Marcus Chong','Julian Arahanga']::TEXT[],ARRAY['saving the world','artificial intelligence (a.i.)','man vs machine','philosophy','prophecy','fortune teller','martial arts','allegory','insurgence','simulated reality','chosen one','dystopia','cyberpunk','gnosticism']::TEXT[],'https://image.tmdb.org/t/p/w500/dXNAPwY7VrqMAo51EKhhCJfaGb5.jpg',NULL,'2026-01-01 00:07:00','2026-01-01 00:07:00'),
(8,'The Lord of the Rings: The Fellowship of the Ring',2001,'Peter Jackson','Young hobbit Frodo Baggins, after inheriting a mysterious ring from his uncle Bilbo, must leave his home in order to keep it from falling into the hands of its evil creator. Along the way, a fellowship is formed to protect the ringbearer and make sure that the ring arrives at its final destination: Mt. Doom, the only place where it can be destroyed.',179,ARRAY['Elijah Wood','Ian McKellen','Viggo Mortensen','Sean Astin','Ian Holm','Liv Tyler','Christopher Lee','Sean Bean']::TEXT[],ARRAY['elves','dwarf','based on novel or book','allegory','obsession','magic','castle','bravery','troll','battle','demon','uncle nephew relationship','fantasy world','dark fantasy','journey']::TEXT[],'https://image.tmdb.org/t/p/w500/6oom5QYQ2yQTMJIbnvbkBL9cHo6.jpg',NULL,'2026-01-01 00:08:00','2026-01-01 00:08:00'),
(9,'Titanic',1997,'James Cameron','101-year-old Rose DeWitt Bukater tells the story of her life aboard the Titanic, 84 years later. A young Rose boards the ship with her mother and fiancé. Meanwhile, Jack Dawson and Fabrizio De Rossi win third-class tickets aboard the ship. Rose tells the whole story from Titanic''s departure through to its death—on its first and last voyage—on April 15, 1912.',194,ARRAY['Leonardo DiCaprio','Kate Winslet','Billy Zane','Kathy Bates','Frances Fisher','Gloria Stuart','Bill Paxton','Bernard Hill']::TEXT[],ARRAY['soulmates','atlantic ocean','evacuation','shipwreck','iceberg','forbidden love','ship','titanic','ocean liner','rich woman poor man','based on true story','tragedy','tragic love','historical fiction','class differences']::TEXT[],'https://image.tmdb.org/t/p/w500/9xjZS2rlVxm8SFx8kPC3aIGCOYQ.jpg',NULL,'2026-01-01 00:09:00','2026-01-01 00:09:00'),
(10,'The Lord of the Rings: The Return of the King',2003,'Peter Jackson','As armies mass for a final battle that will decide the fate of the world--and powerful, ancient forces of Light and Dark compete to determine the outcome--one member of the Fellowship of the Ring is revealed as the noble heir to the throne of the Kings of Men. Yet, the sole hope for triumph over evil lies with a brave hobbit, Frodo, who, accompanied by his loyal friend Sam and the hideous, wretched Gollum, ventures deep into the very dark heart of Mordor on his seemingly impossible quest to destroy the Ring of Power.',201,ARRAY['Elijah Wood','Ian McKellen','Viggo Mortensen','Sean Astin','Andy Serkis','Dominic Monaghan','Billy Boyd','John Noble']::TEXT[],ARRAY['elves','dwarf','based on novel or book','obsession','magic','castle','volcano','giant spider','bravery','kingdom','army','sequel','honor','king','madness']::TEXT[],'https://image.tmdb.org/t/p/w500/rCzpDGLbOoPwLjy3OAm5NUPOTrC.jpg',NULL,'2026-01-01 00:10:00','2026-01-01 00:10:00'),
(11,'The Lord of the Rings: The Two Towers',2002,'Peter Jackson','Frodo Baggins and the other members of the Fellowship continue on their sacred quest to destroy the One Ring--but on separate paths. Their destinies lie at two towers--Orthanc Tower in Isengard, where the corrupt wizard Saruman awaits, and Sauron''s fortress at Barad-dur, deep within the dark lands of Mordor. Frodo and Sam are trekking to Mordor to destroy the One Ring of Power while Gimli, Legolas and Aragorn search for the orc-captured Merry and Pippin. All along, nefarious wizard Saruman awaits the Fellowship members at the Orthanc Tower in Isengard.',179,ARRAY['Elijah Wood','Ian McKellen','Viggo Mortensen','Sean Astin','Andy Serkis','John Rhys-Davies','Orlando Bloom','Bernard Hill']::TEXT[],ARRAY['elves','dwarf','based on novel or book','allegory','obsession','magic','castle','bravery','reincarnation','sequel','mission','split personality','fantasy world','wizard','epic battle']::TEXT[],'https://image.tmdb.org/t/p/w500/5VTN0pR8gcqV3EPUHHfMGnJYN9L.jpg',NULL,'2026-01-01 00:11:00','2026-01-01 00:11:00'),
(12,'Harry Potter and the Chamber of Secrets',2002,'Chris Columbus','Cars fly, trees fight back, and a mysterious house-elf comes to warn Harry Potter at the start of his second year at Hogwarts. Adventure and danger await when bloody writing on a wall announces: The Chamber Of Secrets Has Been Opened. To save Hogwarts will require all of Harry, Ron and Hermione''s magical abilities and courage.',161,ARRAY['Daniel Radcliffe','Rupert Grint','Emma Watson','Kenneth Branagh','Toby Jones','Robbie Coltrane','Richard Harris','Alan Rickman']::TEXT[],ARRAY['flying car','elves','witch','based on novel or book','sword','magic','diary','child hero','school of witchcraft','giant spider','giant snake','black magic','sequel','ghost','nostalgic']::TEXT[],'https://image.tmdb.org/t/p/w500/sdEOH0992YZ0QSxgXNIGLq1ToUi.jpg',NULL,'2026-01-01 00:12:00','2026-01-01 00:12:00'),
(13,'Harry Potter and the Prisoner of Azkaban',2004,'Alfonso Cuarón','Harry Potter''s life is in danger once more as dangerous wizard Sirius Black has escaped from Azkaban Prison and is heading to Hogwarts.',141,ARRAY['Daniel Radcliffe','Rupert Grint','Emma Watson','Robbie Coltrane','Michael Gambon','Gary Oldman','David Thewlis','Timothy Spall']::TEXT[],ARRAY['flying','witch','based on novel or book','bus','traitor','magic','school friend','child hero','school of witchcraft','black magic','time travel','friendship','sequel','school','best friend']::TEXT[],'https://image.tmdb.org/t/p/w500/aWxwnYoe8p2d2fcxOqtvAtJ72Rw.jpg',NULL,'2026-01-01 00:13:00','2026-01-01 00:13:00'),
(14,'Se7en',1995,'David Fincher','Two homicide detectives are on a desperate hunt for a serial killer whose crimes are based on the "seven deadly sins" in this dark and haunting film that takes viewers from the tortured remains of one victim to the next. The seasoned Det. Somerset researches each sin in an effort to get inside the killer''s mind, while his novice partner, Mills, scoffs at his efforts to unravel the case.',127,ARRAY['Morgan Freeman','Brad Pitt','Gwyneth Paltrow','John Cassini','Peter Crombie','Reg E. Cathey','R. Lee Ermey','Daniel Zacapa']::TEXT[],ARRAY['self-fulfilling prophecy','detective','s.w.a.t.','rage and hate','insomnia','sadism','investigation','police','psychopath','murder','serial killer','shootout','religion','corpse','seven deadly sins']::TEXT[],'https://image.tmdb.org/t/p/w500/191nKfP0ehp3uIvWqgPbFmI4lv9.jpg',NULL,'2026-01-01 00:14:00','2026-01-01 00:14:00'),
(15,'The Godfather',1972,'Francis Ford Coppola','Spanning the years 1945 to 1955, a chronicle of the fictional Italian-American Corleone crime family. When organized crime family patriarch, Vito Corleone barely survives an attempt on his life, his youngest son, Michael steps in to take care of the would-be killers, launching a campaign of bloody revenge.',175,ARRAY['Marlon Brando','Al Pacino','James Caan','Robert Duvall','Richard S. Castellano','Diane Keaton','Talia Shire','Gianni Russo']::TEXT[],ARRAY['italy','loss of loved one','love at first sight','based on novel or book','europe','symbolism','gangster','patriarch','organized crime','mafia','religion','revenge motive','crime family','sicilian mafia','religious hypocrisy']::TEXT[],'https://image.tmdb.org/t/p/w500/3bhkrj58Vtu7enYsRolD1fZdja1.jpg',NULL,'2026-01-01 00:15:00','2026-01-01 00:15:00'),
(16,'Captain America: The First Avenger',2011,'Joe Johnston','During World War II, Steve Rogers is a sickly man from Brooklyn who''s transformed into super-soldier Captain America to aid in the war effort. Rogers must stop the Red Skull – Adolf Hitler''s ruthless head of weaponry, and the leader of an organization that intends to use a mysterious device of untold powers for world domination.',124,ARRAY['Chris Evans','Hayley Atwell','Sebastian Stan','Tommy Lee Jones','Hugo Weaving','Dominic Cooper','Richard Armitage','Stanley Tucci']::TEXT[],ARRAY['new york city','world war ii','nazi','superhero','based on comic','super soldier','heroism','brooklyn','aftercreditsstinger','marvel cinematic universe (mcu)','origin story','soldiers','war','admiring','celebratory']::TEXT[],'https://image.tmdb.org/t/p/w500/vSNxAJTlD0r02V9sPYpOjqDZXUK.jpg',NULL,'2026-01-01 00:16:00','2026-01-01 00:16:00'),
